// GPL-2.0: adapted skill checks, gain, teaching, meditation and bandaging from the bundled ServUO scripts.
using Greyhaven.Content;
namespace Greyhaven.Server;
public static class ProgressionSimulation {
 public static double Roll(SessionState s){uint x=s.Adventure.RandomState;x^=x<<13;x^=x>>17;x^=x<<5;s.Adventure.RandomState=x;return x/(double)uint.MaxValue;}
 public static bool Check(SessionState s,string id,double chance){if(!s.Adventure.Enabled)return true;chance=Math.Clamp(chance,0,1);var k=AdventureRules.Skill(s,id);if(k.Uses<int.MaxValue)k.Uses++;bool success=Roll(s)<chance;if(chance>0&&chance<1)Practice(s,k,chance,success);return success;}
 public static bool CheckRange(SessionState s,string id,double min,double max){double value=AdventureRules.Value(s,id);if(!s.Adventure.Enabled)return true;if(value<min)return false;if(value>=max)return true;return Check(s,id,(value-min)/(max-min));}
 static void Practice(SessionState s,SkillProgress k,double chance,bool success){if(k.Lock!="up"||k.Value>=1000||s.Combat.Dead)return;var a=s.Adventure;double gc=((7000-a.Skills.Sum(v=>v.Value))/7000.0+(1000-k.Value)/1000.0)/4+(1-chance)*(success?.5:0)/2;gc=Math.Clamp(gc,.01,1);if(k.Value<100||Roll(s)<=gc){int gain=k.Value<=100?1+Math.Min(3,(int)(Roll(s)*4)):1;gain=Math.Min(gain,1000-k.Value);if(MakeRoom(s,k,gain)){k.Value+=gain;InventoryTransactions.Log(s,$"{AdventureRules.Skills.First(d=>d.Id==k.Id).Name} improves to {k.Value/10.0:0.0}.");}}
  if(s.ElapsedSeconds>=a.NextStatAt&&Roll(s)<.05){a.NextStatAt=s.ElapsedSeconds+.5;GainStat(s,AdventureRules.Skills.First(d=>d.Id==k.Id).Stat);}
 }
 public static bool MakeRoom(SessionState s,SkillProgress target,int gain){int need=Math.Max(0,s.Adventure.Skills.Sum(k=>k.Value)+gain-7000);var down=s.Adventure.Skills.Where(k=>k!=target&&k.Lock=="down").ToList();if(down.Sum(k=>k.Value)<need)return false;foreach(var k in down){int n=Math.Min(need,k.Value);k.Value-=n;need-=n;}return true;}
 static void GainStat(SessionState s,string stat){var a=s.Adventure;int Value(string id)=>id=="str"?a.Strength:id=="dex"?a.Dexterity:a.Intelligence;string Lock(string id)=>id=="str"?a.StrengthLock:id=="dex"?a.DexterityLock:a.IntelligenceLock;void Add(string id,int n){if(id=="str")a.Strength+=n;else if(id=="dex")a.Dexterity+=n;else a.Intelligence+=n;}
  if(Lock(stat)!="up"||Value(stat)>=125)return;if(a.Strength+a.Dexterity+a.Intelligence>=225){var lower=new[]{"str","dex","int"}.FirstOrDefault(id=>id!=stat&&Lock(id)=="down"&&Value(id)>10);if(lower==null)return;Add(lower,-1);}Add(stat,1);InventoryTransactions.Log(s,$"Your {stat.ToUpperInvariant()} increases to {Value(stat)}.");}
 public static bool WeaponHit(SessionState s,EnemyState enemy,string skill){double defend=enemy.Kind=="brineguard"?45:enemy.Kind=="raider"?35:25;return Check(s,skill,(AdventureRules.Value(s,skill)+20)/((defend+20)*2));}
 public static int Damage(SessionState s,int baseDamage){if(!s.Adventure.Enabled)return baseDamage;double bonus=1+s.Adventure.Strength*.003+AdventureRules.Value(s,"tactics")*.00625+AdventureRules.Value(s,"anatomy")*.005;return Math.Max(1,(int)Math.Round(baseDamage*bonus/1.3575));}
 public static int MagicDamage(SessionState s,int damage)=>!s.Adventure.Enabled?damage:Math.Max(1,(int)Math.Round(damage*(.5+AdventureRules.Value(s,"evalint")*.015)*(1+s.Adventure.Intelligence*.001)/.832));
 public static bool Spell(SessionState s,string name){if(!s.Adventure.Enabled)return true;int circle=name switch{"Dawn"=>0,"Ember"=>1,"Ward"=>1,"Bind"=>2,"Venom"=>2,"Renew"=>2,"Storm"=>3,_=>3};double average=100.0/7*circle;bool success=CheckRange(s,"magery",average-20,average+20);CheckRange(s,"evalint",0,100);return success;}
 public static bool Incoming(SessionState s,bool magic){if(!s.Adventure.Enabled)return true;if(magic){bool resisted=Check(s,"resist",AdventureRules.Value(s,"resist")/200);return !resisted;}bool hit=Roll(s)<(55/((Math.Max(AdventureRules.Value(s,"swords"),AdventureRules.Value(s,"wrestling"))+20)*2));if(hit&&s.Items.Any(i=>i.Where=="equipped"&&i.Definition.EndsWith("shield"))&&Check(s,"parry",AdventureRules.Value(s,"parry")/400))return false;return hit;}
 public static void Stop(SessionState s){s.Adventure.Meditating=false;}
 public static void Consume(SessionState s,WorldItem i,int amount){i.Amount-=amount;if(i.Amount>0)return;s.Items.Remove(i);for(int n=0;n<10;n++)if(s.Quickbar[n]=="item:"+i.Id)s.Quickbar[n]="";}
 public static void Pay(SessionState s,int amount){if(InventoryRules.Marks(s)<amount)throw new ContentException("Not enough silver marks.");foreach(var i in s.Items.Where(i=>i.Definition==InventoryRules.Currency&&i.QuestId==""&&InventoryRules.Carried(s,i)).ToList()){int n=Math.Min(i.Amount,amount);Consume(s,i,n);amount-=n;if(amount==0)return;}}
 public static string Train(ContentPackage p,SessionState s,Command c){var trainer=p.AdventureCatalog.Trainers.FirstOrDefault(t=>t.NpcId==c.TargetId&&t.Skill==c.ItemId)??throw new ContentException("That resident cannot teach this skill.");AdventureSimulation.RequireNpc(p,s,trainer.NpcId);var skill=AdventureRules.Skill(s,c.ItemId);if(skill.Lock!="up")throw new ContentException("Set this skill to gain before training.");int ceiling=Math.Min(420,trainer.Value/3);int amount=Math.Min(Math.Clamp(c.Amount,1,100),ceiling-skill.Value);if(amount<=0)throw new ContentException("You already know everything this teacher can offer.");if(!MakeRoom(s,skill,amount))throw new ContentException("The total skill cap leaves no room. Set another skill to decrease.");Pay(s,amount);skill.Value+=amount;return $"Learned {amount/10.0:0.0} {AdventureRules.Skills.First(d=>d.Id==skill.Id).Name} for {amount} marks.";}
 public static string Meditate(SessionState s){if(s.ElapsedSeconds<s.Adventure.NextSkillAt)throw new ContentException("Wait before attempting another active skill.");if(s.Combat.Mana>=60)throw new ContentException("Your mana is already full.");if(s.Combat.Cast!=null||s.Combat.WarMode)throw new ContentException("Leave war mode and finish casting first.");if(s.Items.Any(i=>i.Where=="equipped"&&(i.Definition.EndsWith("sword")||i.Definition.EndsWith("shield")||i.Definition.EndsWith("greatblade"))))throw new ContentException("Put your weapon and shield in your backpack before meditating.");s.Adventure.NextSkillAt=s.ElapsedSeconds+10;double chance=(50+(AdventureRules.Value(s,"meditation")-(60-s.Combat.Mana))*2)/100;s.Adventure.Meditating=Check(s,"meditation",chance);return s.Adventure.Meditating?"You settle into a meditative trance. Movement and action break your focus.":"Your thoughts will not settle; try again after a short pause.";}
 public static string Bandage(SessionState s){Stop(s);if(s.Adventure.BandageAt>0)throw new ContentException("You are already applying a bandage.");if(s.Combat.Health>=100)throw new ContentException("You have no wounds to bandage.");var item=s.Items.FirstOrDefault(i=>i.Definition=="greyhaven.item.bandage"&&i.QuestId==""&&InventoryRules.Carried(s,i))??throw new ContentException("Carry a clean bandage first.");Consume(s,item,1);s.Adventure.BandageAt=s.ElapsedSeconds+Math.Clamp(Math.Ceiling(11-s.Adventure.Dexterity/20.0),4,8);s.Adventure.BandageX=s.X;s.Adventure.BandageY=s.Y;s.Adventure.BandageSlips=0;return "You begin dressing your wounds.";}
 public static void Advance(ContentPackage p,SessionState s,double dt){var a=s.Adventure;if(!a.Enabled||s.Paused)return;if(a.Meditating&&(s.Combat.Dead||s.Combat.Cast!=null||s.Combat.WarMode))a.Meditating=false;if(a.Meditating)s.Combat.Mana=Math.Min(60,s.Combat.Mana+(int)(Math.Floor(s.ElapsedSeconds)-Math.Floor(s.ElapsedSeconds-dt))*2);if(a.Meditating&&s.Combat.Mana==60)a.Meditating=false;
  if(a.BandageAt>0&&(s.Combat.Dead||CombatRules.Distance(s.X,s.Y,a.BandageX,a.BandageY)>1)){a.BandageAt=0;InventoryTransactions.Log(s,"Your bandaging is interrupted.");}else if(a.BandageAt>0&&s.ElapsedSeconds>=a.BandageAt){a.BandageAt=0;double healing=AdventureRules.Value(s,"healing"),anatomy=AdventureRules.Value(s,"anatomy");bool success=Check(s,"healing",(healing+10)/100-a.BandageSlips*.02);CheckRange(s,"anatomy",0,100);if(success){int health=(int)(anatomy/8+healing/5+4+Roll(s)*(anatomy/6+healing/2.5-anatomy/8-healing/5));s.Combat.Health=Math.Min(100,s.Combat.Health+Math.Max(1,health));InventoryTransactions.Log(s,"The clean bandage closes your wounds.");}else InventoryTransactions.Log(s,"The bandage does not hold; the wounds remain.");}
 }
}
